<script setup lang="ts">
import { ref,watch,nextTick,onBeforeUnmount } from 'vue'
import * as api from '@/api/wall'
import { ApiError } from '@/api/client'
import { errorMessage } from '@/api/identity'
import {useWallStore} from '@/stores/wall'
import { useAuthStore } from '@/stores/auth'
import { useAuthDialogStore } from '@/stores/auth-dialog'
import type { WallMessage,WallComment } from '@/wall/types'
import WallFormattedText from './WallFormattedText.vue'
const props=defineProps<{open:boolean;note:WallMessage|null}>(),emit=defineEmits<{close:[];refresh:[]}>(),auth=useAuthStore(),login=useAuthDialogStore()
const dialog=ref<HTMLDialogElement>(),reportDialog=ref<HTMLDialogElement>(),current=ref<WallMessage|null>(null),comments=ref<WallComment[]>([]),cursor=ref<string|null>(null),more=ref(false),busy=ref(false),error=ref(''),success=ref(''),reply=ref(''),replyPending=ref<{requestId:string;text:string}|null>(null),reportType=ref<'MESSAGE'|'COMMENT'>('MESSAGE'),reportId=ref(''),reason=ref('OTHER'),reportText=ref(''),reportError=ref('')
const wall=useWallStore();let accountKey=auth.user?.id;
function rememberReply(){if(current.value&&accountKey&&accountKey===auth.user?.id)wall.replyDrafts[current.value.id]={text:reply.value,pending:replyPending.value?{...replyPending.value}:null}}
let generation=0;const reportPending=ref<Parameters<typeof api.reportContent>[0]|null>(null)
const deleteRequests=new Map<string,string>()
// Native modal dialogs occupy the browser top layer, above the shared login overlay.
watch(()=>login.open,async opened=>{if(opened){reportDialog.value?.close();dialog.value?.close()}else{await nextTick();if(props.open&&current.value&&!login.open&&!dialog.value?.open)dialog.value?.showModal()}})
function loggedIn(){if(auth.user)return true;login.request('/wall');return false}
watch(()=>`${props.open}:${props.note?.id??''}:${auth.user?.id??'guest'}`,async()=>{rememberReply();wall.bindIdentity(auth.user?.id??'guest');accountKey=auth.user?.id;const g=++generation;current.value=null;reportId.value='';reportText.value='';reportError.value='';reason.value='OTHER';error.value='';success.value='';reply.value='';replyPending.value=null;comments.value=[];cursor.value=null;more.value=false;reportPending.value=null;reportDialog.value?.close();busy.value=false;if(!props.open){dialog.value?.close();return}current.value=props.note;const saved=current.value?wall.replyDrafts[current.value.id]:undefined;if(saved){reply.value=saved.text;replyPending.value=saved.pending?{...saved.pending}:null}await nextTick();if(g!==generation)return;if(!login.open)dialog.value?.showModal();if(!current.value||current.value.status==='HIDDEN')return;try{const [message,page]=await Promise.all([api.message(current.value.id),api.listComments(current.value.id)]);if(g!==generation)return;current.value=message;comments.value=page.items;cursor.value=page.nextCursor;more.value=page.hasMore}catch(e){if(g===generation)error.value=errorMessage(e)}})
async function like(){if(!current.value||busy.value||!loggedIn())return;const g=generation;busy.value=true;error.value='';try{const item=await api.setLike(current.value.id,!current.value.liked);if(g!==generation)return;current.value=item;emit('refresh')}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
async function submitReply(){if(!current.value||busy.value||!loggedIn())return;const g=generation,id=current.value.id;busy.value=true;error.value='';const previous=!!replyPending.value;if(!replyPending.value)replyPending.value={requestId:crypto.randomUUID(),text:reply.value};rememberReply();try{if(previous){try{const status=await api.requestStatus(replyPending.value.requestId);if(g!==generation)return;if(status.completed){reply.value='';replyPending.value=null;rememberReply();const page=await api.listComments(id);if(g!==generation)return;comments.value=page.items;cursor.value=page.nextCursor;more.value=page.hasMore;success.value='评论发布结果已确认。';emit('refresh');return}}catch(e){if(!(e instanceof ApiError&&e.status===404))throw e}}const result=await api.createComment(id,replyPending.value!);if(g!==generation)return;if(!comments.value.some(c=>c.id===result.id))comments.value.unshift(result);reply.value='';replyPending.value=null;rememberReply();emit('refresh')}catch(e){if(g===generation){error.value=errorMessage(e);if(e instanceof ApiError&&[400,401,403,404,409,429].includes(e.status))replyPending.value=null;rememberReply()}}finally{if(g===generation)busy.value=false}}
onBeforeUnmount(()=>{rememberReply();generation++})

async function remove(comment?:WallComment){if(!current.value||busy.value||!loggedIn()||!confirm(comment?'删除这条评论？':'删除自己的这条留言？'))return;const g=generation;busy.value=true;error.value='';const key=comment?'comment:'+comment.id:'message:'+current.value.id;if(!deleteRequests.has(key))deleteRequests.set(key,crypto.randomUUID());try{const command={requestId:deleteRequests.get(key)!,expectedVersion:comment?.version??current.value.version};if(comment)await api.deleteComment(comment.id,command);else await api.deleteOwnMessage(current.value.id,command);if(g!==generation)return;deleteRequests.delete(key);if(comment)comments.value=comments.value.filter(c=>c.id!==comment.id);else emit('close');emit('refresh')}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
function openReport(comment?:WallComment){if(!current.value||!loggedIn())return;reportType.value=comment?'COMMENT':'MESSAGE';reportId.value=comment?.id??current.value.id;reportText.value='';reportError.value='';reportPending.value=null;reportDialog.value?.showModal()}
async function report(){if(busy.value||!loggedIn())return;const g=generation;busy.value=true;reportError.value='';if(!reportPending.value)reportPending.value={requestId:crypto.randomUUID(),targetType:reportType.value,targetId:reportId.value,reason:reason.value,detail:reportText.value};try{await api.reportContent(reportPending.value!);if(g!==generation)return;reportPending.value=null;reportDialog.value?.close();success.value='举报已提交给管理员，不会自动隐藏留言。'}catch(e){if(g===generation){reportError.value=errorMessage(e);if(e instanceof ApiError&&[400,401,403,404,409,429].includes(e.status))reportPending.value=null}}finally{if(g===generation)busy.value=false}}
async function loadMore(){if(!current.value||!cursor.value||busy.value)return;const g=generation;busy.value=true;try{const page=await api.listComments(current.value.id,cursor.value);if(g!==generation)return;comments.value.push(...page.items.filter(c=>!comments.value.some(x=>x.id===c.id)));cursor.value=page.nextCursor;more.value=page.hasMore}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
</script>
<template>
 <dialog ref="dialog" class="wall-dialog" aria-labelledby="wall-detail-heading" @cancel.prevent="emit('close')"><header class="wall-dialog-heading"><div><h2 id="wall-detail-heading">{{current?.author.displayName}}</h2><span class="muted">{{current?.status==='HIDDEN'?'已隐藏':current?.editedByAdmin?'管理员已编辑':'学习交流'}}</span></div><button aria-label="关闭留言详情" @click="emit('close')">×</button></header><h3 v-if="current?.title">{{current.title}}</h3><p class="wall-detail-text"><WallFormattedText :text="current?.text??''" :announcement="current?.kind==='ANNOUNCEMENT'" /></p><p v-if="current?.authorReason" class="wall-hidden-reason">处理原因：{{current.authorReason}}</p>
 <p v-if="error" class="wall-error" role="alert">{{error}}</p><p v-if="success" class="wall-success" role="status">{{success}}</p><div class="wall-detail-actions"><template v-if="current?.status!=='HIDDEN'"><button :disabled="busy" :aria-pressed="current?.liked" :aria-label="current?.liked?'取消点赞':'点赞'" @click="like">{{current?.liked?'♥':'♡'}} {{current?.likes}}</button><button v-if="!current?.owned" :disabled="busy" @click="openReport()">举报留言</button></template><button v-if="current?.owned" class="wall-danger" :disabled="busy" @click="remove()">删除我的留言</button></div>
 <template v-if="current?.status!=='HIDDEN'"><h3 class="wall-reply-heading">讨论</h3><p v-if="!comments.length" class="muted">还没有讨论，来留下第一句鼓励吧。</p><article v-for="comment in comments" :key="comment.id" class="wall-reply"><header><span>{{comment.author.displayName}}</span><button :disabled="busy" @click="comment.owned?remove(comment):openReport(comment)">{{comment.owned?'删除':'举报'}}</button></header><p>{{comment.text}}</p></article><button v-if="more" :disabled="busy" @click="loadMore">加载更多评论</button>
 <form class="wall-reply-form" @submit.prevent="submitReply"><label for="wall-reply-text">留下你的鼓励或想法</label><textarea id="wall-reply-text" v-model="reply" :disabled="!!replyPending" required placeholder="友好讨论，一起进步。"/><p class="wall-word-count">{{Array.from(reply).length}} / 500 字</p><div class="wall-form-actions"><button class="button-primary" :disabled="busy||!reply.trim()||Array.from(reply).length>500">{{replyPending&&!busy?'确认评论结果':'发表评论'}}</button></div></form></template>
 </dialog>
 <dialog ref="reportDialog" class="wall-dialog" aria-labelledby="wall-report-title" @cancel.prevent="!busy&&reportDialog?.close()"><form @submit.prevent="report"><header class="wall-dialog-heading"><div><h2 id="wall-report-title">举报内容</h2><p class="muted">举报交给管理员处理，不会自动隐藏内容。</p></div><button type="button" aria-label="关闭举报" :disabled="busy" @click="reportDialog?.close()">×</button></header><label for="wall-report-reason">举报原因</label><select id="wall-report-reason" v-model="reason" :disabled="!!reportPending"><option value="SPAM">广告或垃圾内容</option><option value="UNFRIENDLY">不友善的言论</option><option value="PRIVACY">泄露个人信息</option><option value="OTHER">其他</option></select><label for="wall-report-text">补充说明（选填）</label><textarea id="wall-report-text" v-model="reportText" :disabled="!!reportPending" maxlength="500"/><p v-if="reportError" role="alert" class="wall-error">{{reportError}}</p><div class="wall-form-actions"><button type="button" :disabled="busy" @click="reportDialog?.close()">取消</button><button class="button-primary" :disabled="busy">提交举报</button></div></form></dialog>
</template>
